        ownerPageDto.setSize(ownerPage.getSize());
        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
        return ownerPageDto;
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Joins a deliberately-shared household. When the create request opts in via
 * {@code sharesHousehold} and an existing owner has the same last name and address (the address in
 * its normalized form and the last name case-insensitively with whitespace collapsed, the same rule
 * {@link CheckOwnerHouseholdUnique} uses), the new owner and the existing household member(s) are
 * given the same, stable
 * {@code householdId}. If a matching owner already carries a household id it is reused; otherwise a
 * new id is derived from the household's normalized last name and address, so the same household
 * always yields the same value. Does nothing when the request does not opt in or no matching owner
 * exists — a lone owner has no household to share.
 */
public class AssignHousehold {

    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository) {
        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        String lastName = normalizeName(owner.getLastName());
        String address = AddressNormalizer.normalize(owner.getAddress());
        List<Owner> household = new ArrayList<>();
        String existingId = null;
        for (Owner existing : ownerRepository.findAll()) {
            if (lastName.equals(normalizeName(existing.getLastName()))
                    && address.equals(AddressNormalizer.normalize(existing.getAddress()))) {
                household.add(existing);
                if (existingId == null && existing.getHouseholdId() != null) {
                    existingId = existing.getHouseholdId();
                }
            }
        }
        if (household.isEmpty()) {
            return; // nobody to share a household with
        }
        String householdId = existingId != null ? existingId : deriveHouseholdId(lastName, address);
        owner.setHouseholdId(householdId);
        for (Owner member : household) {
            if (member.getHouseholdId() == null) {
                member.setHouseholdId(householdId);
                ownerRepository.save(member);
            }
        }
    }

    /** A stable {@code HH-<12 upper hex>} id derived from the household's normalized identity. */
    private static String deriveHouseholdId(String lastName, String address) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                    .digest((lastName + "|" + address).getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder("HH-");
            for (int i = 0; i < 6; i++) {
                sb.append(String.format("%02X", digest[i]));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 unavailable", e);
        }
    }

    /** Trim, collapse internal whitespace runs to a single space, and lower-case. */
    private static String normalizeName(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

/**
 * Converts raw telephone numbers into E.164 form ('+' followed by 8 to 15 digits). A leading '+'
 * and country code are kept when present, otherwise country code '+61' is assumed and a single
 * leading '0' is dropped from the national digits. Spaces, dashes and brackets are stripped.
 *
 * <p>Not a function class (never wired into a YAML pipeline) — just shared logic for
 * {@link NormalizeOwnerTelephone} and {@link CheckOwnerTelephoneUnique}.
 */
public final class TelephoneE164 {

    private TelephoneE164() {
    }

    /**
     * Converts {@code telephone} into E.164, or returns {@code null} when it cannot form a valid
     * E.164 number.
     */
    public static String toE164(String telephone) {
        if (telephone == null) {
            return null;
        }
        // Strip spaces, dashes and brackets.
        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
        String digits;
        if (cleaned.startsWith("+")) {
            // Keep the explicit country code; the remainder must be all digits.
            digits = cleaned.substring(1);
        }
        else {
            // Assume '+61' and drop a single leading '0' from the national digits.
            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
            digits = "61" + national;
        }
        if (!digits.matches("\\d{8,15}")) {
            return null;
        }
        return "+" + digits;
    }

    /**
     * Checks the national-number length of an E.164 number against its country code: '+61'
     * requires 9 national digits and '+1' requires 10. Country codes without a per-country length
     * rule here pass (only the generic 8-to-15-digit bound applies to them). Expects {@code e164}
     * already in valid E.164 form (a '+' followed by 8 to 15 digits), as returned by
     * {@link #toE164}; a {@code null} or non-E.164 value fails.
     */
    public static boolean nationalLengthValid(String e164) {
        if (e164 == null || !e164.startsWith("+")) {
            return false;
        }
        String digits = e164.substring(1);
        // Longest known country code first: '+1' would also prefix-match, but '+61' never
        // starts with '1' and '+1' never starts with '61', so the two do not collide.
        if (digits.startsWith("61")) {
            return digits.length() - 2 == 9;
        }
        if (digits.startsWith("1")) {
            return digits.length() - 1 == 10;
        }
        return true;
    }
}
